:root {
  --om-ink: #202020;
  --om-secondary: #606060;
  --om-muted: #737373;
  --om-paper: #fafafa;
  --om-panel: #fff;
  --om-soft: #eee;
  --om-line: #dedede;
  --om-warning: #765820;
  --om-danger: #a13232;
  --om-radius: 8px;
  --om-sans:
    "Noto Sans CJK SC", "PingFang SC", "Microsoft YaHei", system-ui, sans-s

h1,
h2 {
  font-family: var(--om-serif);
  font-weight: 600;
  line-height: 1.6;
}
h1 {
  font-size: 30px;
}
h2 {
  font-size: 24px;
}
small {
  font-size: 12px;
  color: var(--om-muted);
}

button,
input,
textarea,
select {
  font: inherit;
}
button {
  cursor: pointer;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

input,
textarea,
select {
  max-width: 100%;
  border: 1px solid var(--om-line);
  border-radius: 6px;
  padding: 10px 12px;
  background: white;
  color: var(--om-ink);
}
textarea {
  resize: vertical;
}
label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 13px;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible,
summary:focus-visible {
  outline: 2px solid #666;
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

/* Shared neutral syntax theme; also applies to Markdown fences. */
:is(.om-code-view, .om-markdown) .hljs-keyword,
:is(.om-code-view, .om-markdown) .hljs-selector-tag { color: #202020; font-weight: 700; }
:is(.om-code-view, .om-markdown) .hljs-comment,
:is(.om-code-view, .om-markdown) .hljs-quote { color: #737373; fon
